<x-capstone::dialog id="users-delete" title="Hapus User"><form @submit.prevent="remove()" class="mt-4 space-y-4"><p class="text-sm">Hapus akun berikut? User yang dihapus tidak dapat login.</p><ul class="list-inside list-disc text-sm"><template x-for="user in deleting" :key="user.id"><li x-text="user.name"></li></template></ul><p class="whitespace-pre-wrap text-sm text-destructive" role="alert" x-text="errors.root"></p><div class="flex justify-end gap-2"><x-capstone::button variant="outline" @click="$el.closest('dialog').close()" ::disabled="saving">Batal</x-capstone::button><x-capstone::button type="submit" variant="destructive" ::disabled="saving"><span x-text="saving?'Menghapus...':'Hapus User'"></span></x-capstone::button></div></form></x-capstone::dialog>
